#!/bin/bash
cd ~/github/remotion-claw/podcast-ep2

edge-tts --voice "en-US-GuyNeural" --text "And I'm Alex. This week we're talking about the biggest security release OpenClaw has ever shipped." --write-media a1.mp3 && echo "✓ a1"
