edge-tts --voice "en-US-GuyNeural" --text "No more separate browser profiles. No more logging into everything twice. Just attach to Chrome and go." --write-media a9.mp3 && echo "✓ a9"
edge-tts --voice "en-US-GuyNeural" --text "That's powerful but also kind of terrifying from a security perspective." --write-media a10.mp3 && echo "✓ a10"
edge-tts --voice "en-US-GuyNeural" --text "Makes sense. What about the Dashboard v2 rebuild?" --write-media a11.mp3 && echo "✓ a11"
edge-tts --voice "en-US-GuyNeural" --text "The old dashboard was pretty rough. Just a basic status page basically." --write-media a12.mp3 && echo "✓ a12"
edge-tts --voice "en-US-GuyNeural" --text "Speaking of fleets, the Android app had a massive month too." --write-media a13.mp3 && echo "✓ a13"
